WITH prev_events AS (SELECT *, LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC) AS prev_paid_at FROM payments), gaps AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM prev_events), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT DATE_TRUNC('QUARTER', paid_at) AS quarter_start, status, CASE WHEN session_no >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS session_no_tier, ROUND(SUM(session_no) / NULLIF(COUNT(CASE WHEN status = 'FAILED' THEN 1 END), 0), 2) AS session_no_per_failed, APPROX_PERCENTILE(session_no, ARRAY(0.25, 0.5, 0.75)) AS session_no_quartiles, SIZE(COLLECT_SET(status)) AS num_status, PERCENT_RANK() OVER (PARTITION BY DATE_TRUNC('QUARTER', paid_at) ORDER BY SIZE(COLLECT_SET(status)) DESC) AS num_status_percent_rank FROM sessionized GROUP BY 1, 2, 3 HAVING SIZE(COLLECT_SET(status)) > 1 ORDER BY status DESC;
